// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, address target, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(value <= address(this).balance);
        vm.deal(address(c), value);
        bool ok;
        vm.prank(caller);
        try c.sendMoney(target, value) { ok = true; } catch { ok = false; }
        assertTrue(caller == c.owner() || !ok);
    }
}
